import React from "react";
import { Image, View } from "react-native";

const logoBase64 =
  "data:image/png;base64,";

export default function LpLogo({ width = 40, height = 40 }) {
  return (
    <View>
      <Image source={{ uri: logoBase64 }} style={{ width, height }} resizeMode="contain" />
    </View>
  );
}
